// aim.cpp — aim assist for the Mesa client.
//
// Projects candidate entity head positions into screen space using the
// camera's view-projection matrix, picks the best target inside a circular
// cone around the crosshair, and returns a smoothed per-frame crosshair delta.
//
// All inputs come from the client's own game state; this module only does math.

#include <cmath>
#include <cstdint>
#include <limits>
#include <vector>

namespace mesa::aim {

struct Vec2 { float x = 0.f, y = 0.f; };
struct Vec3 { float x = 0.f, y = 0.f, z = 0.f; };

// Row-major 4x4, column-vector convention: clip = M * [x y z 1]^T
struct Mat4 { float m[4][4]; };

struct Entity {
    uint32_t id = 0;
    Vec3     head;            // world-space head position
    bool     alive   = true;
    bool     visible = true;  // result of the client's own LOS check
    bool     friendly = false;
};

struct Viewport {
    float width  = 1920.f;
    float height = 1080.f;
};

struct Settings {
    float coneRadiusPx = 240.f;  // max distance from crosshair to consider a target
    float smoothing    = 12.f;   // higher = faster convergence (1/s), exponential
    float maxStepPx    = 60.f;   // clamp on per-frame delta magnitude
    float deadzonePx   = 0.5f;   // below this, emit zero delta
};

struct Result {
    bool     hasTarget = false;
    uint32_t targetId  = 0;
    Vec2     targetScreen;       // projected head position in pixels
    Vec2     delta;              // crosshair delta to apply this frame (pixels)
    float    distancePx = 0.f;   // target distance from crosshair before smoothing
};

// World -> screen. Returns false if the point is behind the camera or
// outside the clip volume's near plane.
bool worldToScreen(const Vec3& p, const Mat4& vp, const Viewport& view, Vec2& out) {
    const float cx = vp.m[0][0]*p.x + vp.m[0][1]*p.y + vp.m[0][2]*p.z + vp.m[0][3];
    const float cy = vp.m[1][0]*p.x + vp.m[1][1]*p.y + vp.m[1][2]*p.z + vp.m[1][3];
    const float cw = vp.m[3][0]*p.x + vp.m[3][1]*p.y + vp.m[3][2]*p.z + vp.m[3][3];

    if (cw <= 1e-4f) return false;  // behind camera / on near plane

    const float ndcX = cx / cw;
    const float ndcY = cy / cw;

    out.x = (ndcX * 0.5f + 0.5f) * view.width;
    out.y = (1.0f - (ndcY * 0.5f + 0.5f)) * view.height;  // NDC +Y up -> screen +Y down
    return true;
}

// Selects the target closest to the crosshair inside the cone and returns
// a smoothed delta toward it. `dt` is frame time in seconds.
Result compute(const std::vector<Entity>& entities,
               const Mat4& viewProj,
               const Viewport& view,
               const Settings& cfg,
               float dt) {
    Result r;
    const Vec2 center{ view.width * 0.5f, view.height * 0.5f };
    const float coneSq = cfg.coneRadiusPx * cfg.coneRadiusPx;
    float bestSq = std::numeric_limits<float>::max();

    for (const Entity& e : entities) {
        if (!e.alive || !e.visible || e.friendly) continue;

        Vec2 s;
        if (!worldToScreen(e.head, viewProj, view, s)) continue;

        const float dx = s.x - center.x;
        const float dy = s.y - center.y;
        const float dSq = dx*dx + dy*dy;

        if (dSq > coneSq || dSq >= bestSq) continue;

        bestSq          = dSq;
        r.hasTarget     = true;
        r.targetId      = e.id;
        r.targetScreen  = s;
    }

    if (!r.hasTarget) return r;

    const float ox = r.targetScreen.x - center.x;
    const float oy = r.targetScreen.y - center.y;
    r.distancePx = std::sqrt(bestSq);

    if (r.distancePx < cfg.deadzonePx) return r;  // delta stays zero

    // Frame-rate independent exponential approach: fraction of the remaining
    // offset to cover this frame.
    const float alpha = 1.0f - std::exp(-cfg.smoothing * (dt > 0.f ? dt : 0.f));
    float sx = ox * alpha;
    float sy = oy * alpha;

    const float stepLen = std::sqrt(sx*sx + sy*sy);
    if (stepLen > cfg.maxStepPx && stepLen > 0.f) {
        const float k = cfg.maxStepPx / stepLen;
        sx *= k;
        sy *= k;
    }

    r.delta = { sx, sy };
    return r;
}

} // namespace mesa::aim
